local function submitKey(key)
    key = M.cleanKey(key)
    if key == "" then
        Library:Notify({Title="⚠️ Kunci belum dimasukkan", Description="Silakan masukkan kunci Anda.", Time=3})
        return
    end
    Library:Notify({Title="🔑 Memeriksa", Description="Memvalidasi kunci Anda...", Time=2})

    -- NEW backend: validate the key + get this game's scripts in one call.
    local data, err = M.validateKeyNew(key)
    if type(data) ~= "table" then
        local msg = "Kunci itu tidak valid. Periksa dan coba lagi."
        if err == "wrong_game" then
            msg = "Kunci ini untuk game lain. Dapatkan kunci untuk game ini."
        elseif err == "network" or err == "no_request" then
            msg = "Kesalahan jaringan. Silakan coba lagi."
        end
        Library:Notify({Title="❌ Kunci tidak valid", Description=msg, Time=5})
        return
    end

    local scripts = data.scripts or {}
    if #scripts == 0 then
        Library:Notify({Title="🔓 Kunci valid", Description="Belum ada skrip yang diatur untuk game ini.", Time=5})
        return
    end

    -- Valid — remember the key for next time, close this GUI, show the selector.
    M.saveKeyLocal(key)
    Library:Notify({
        Title = "🔓 Kunci valid",
        Description = (#scripts == 1) and "Memuat skrip..." or "Pilih skrip...",
        Time = 3,
    })
    task.wait(0.4)
    pcall(function() Library:Unload() end)
    M.showSelector(scripts)
end

local function readKeyFromBox()
    local raw
    pcall(function()
        local holder = Options and Options.KeyInput and Options.KeyInput.Holder
        local box = holder and holder:FindFirstChildOfClass("TextBox")
        if box then raw = box.Text end
    end)
    local key = M.cleanKey(raw)
    if key == "" then key = M.cleanKey(Options and Options.KeyInput and Options.KeyInput.Value) end
    if key == "" then key = M.cleanKey(keyInputValue) end
    return key
end

